"""Tests for fsutil args, deps, exceptions and metadata modules."""

import os

import pytest

import fsutil
from fsutil.exceptions import FSUtilError


class TestGetPath:
    def test_str(self):
        assert fsutil.get_path("/some/path") == "/some/path"

    def test_pathlike(self):
        assert fsutil.get_path(os.path.join("a", "b")) == os.path.join("a", "b")

    def test_none(self):
        with pytest.raises(TypeError):
            fsutil.get_path(None)
        assert fsutil.get_path(None, allow_none=True) is None

    def test_invalid_type(self):
        with pytest.raises(TypeError):
            fsutil.get_path(123)


class TestRequireRequests:
    def test_require_requests(self):
        requests = fsutil.require_requests()
        assert requests.__name__ == "requests"


class TestExceptions:
    def test_fsutil_error(self):
        assert issubclass(FSUtilError, Exception)
        with pytest.raises(FSUtilError):
            raise FSUtilError("error")


class TestMetadata:
    def test_metadata_attributes(self):
        assert isinstance(fsutil.__version__, str)
        assert fsutil.__version__
        assert isinstance(fsutil.__author__, str)
        assert isinstance(fsutil.__title__, str)
        assert isinstance(fsutil.__license__, str)
        assert isinstance(fsutil.__copyright__, str)
        assert isinstance(fsutil.__description__, str)
        assert isinstance(fsutil.__email__, str)

    def test_metadata_module(self):
        from fsutil import metadata

        assert metadata.__version__ == fsutil.__version__

"""Tests for fsutil paths module."""

import os

import pytest

import fsutil


class TestJoin:
    def test_join_path(self):
        assert fsutil.join_path("/home/user", "documents", "file.txt") == os.path.join(
            "/home/user", "documents", "file.txt"
        )

    def test_join_path_single(self):
        assert fsutil.join_path("dir1", "dir2", "file.txt") == os.path.join("dir1", "dir2", "file.txt")

    def test_join_filepath(self):
        assert fsutil.join_filepath("/home/user", "document.pdf") == os.path.join(
            "/home/user", "document.pdf"
        )

    def test_join_filename(self):
        assert fsutil.join_filename("document", "pdf") == "document.pdf"
        assert fsutil.join_filename("document", ".pdf") == "document.pdf"
        assert fsutil.join_filename("document", "") == "document"


class TestSplit:
    def test_split_path(self):
        parts = fsutil.split_path(os.path.join("dir1", "dir2", "file.txt"))
        assert parts == ["dir1", "dir2", "file.txt"]

    def test_split_path_absolute(self):
        parts = fsutil.split_path(os.path.join(os.sep, "home", "user"))
        assert parts[-2:] == ["home", "user"]

    def test_split_filepath(self):
        dirpath, filename = fsutil.split_filepath(os.path.join("dir1", "dir2", "file.txt"))
        assert dirpath == os.path.join("dir1", "dir2")
        assert filename == "file.txt"

    def test_split_filename(self):
        basename, extension = fsutil.split_filename("document.pdf")
        assert basename == "document"
        assert extension == "pdf"

    def test_split_filename_path(self):
        basename, extension = fsutil.split_filename(os.path.join("some", "dir", "archive.tar.gz"))
        assert basename == "archive.tar"
        assert extension == "gz"

    def test_split_filename_no_extension(self):
        basename, extension = fsutil.split_filename("README")
        assert basename == "README"
        assert extension == ""


class TestInfo:
    def test_get_filename(self):
        assert fsutil.get_filename(os.path.join("some", "dir", "file.txt")) == "file.txt"

    def test_get_file_basename(self):
        assert fsutil.get_file_basename(os.path.join("some", "dir", "file.txt")) == "file"

    def test_get_file_extension(self):
        assert fsutil.get_file_extension(os.path.join("some", "dir", "file.txt")) == "txt"

    def test_get_parent_dir(self):
        path = os.path.join("home", "user", "documents", "file.txt")
        assert fsutil.get_parent_dir(path) == os.path.join("home", "user", "documents")
        assert fsutil.get_parent_dir(path, levels=2) == os.path.join("home", "user")


class TestTransform:
    def test_transform_filepath(self):
        path = os.path.join("dir", "file.txt")
        transformed = fsutil.transform_filepath(path, str.upper)
        assert transformed == os.path.join("DIR", "FILE.TXT")

    def test_transform_filepath_no_dir(self):
        assert fsutil.transform_filepath("file.txt", str.upper) == "FILE.TXT"


class TestPathValidation:
    def test_invalid_path_types(self):
        for func in (fsutil.join_path, fsutil.get_filename, fsutil.split_path):
            with pytest.raises(TypeError):
                func(123)
